const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/seqconc";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "order.test.mjs"), [
  "import { test } from 'vitest'",
  "import { appendFileSync } from 'node:fs'",
  "const delay = (ms) => new Promise((r) => setTimeout(r, ms))",
  "const log = (s) => appendFileSync(new URL('./order.txt', import.meta.url), s)",
  "test('slow', { concurrent: false }, async () => { await delay(400); log('slow,') })",
  "test('fast', { concurrent: false }, async () => { await delay(20); log('fast,') })",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--sequence.concurrent"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
const orderFile = path.join(dir, "order.txt");
if (r.status !== 0 || !fs.existsSync(orderFile)) {
  console.error("ERROR: vitest run did not pass or wrote no order (exit " + r.status + ")");
  process.exit(2);
}
const order = fs.readFileSync(orderFile, "utf8");
console.log("completion order: " + order);
if (order === "slow,fast,") {
  console.log("PASS: tests with concurrent: false ran one after another under --sequence.concurrent");
  process.exit(0);
}
if (order === "fast,slow,") {
  console.error("FAIL: tests with concurrent: false still ran concurrently under --sequence.concurrent");
  process.exit(1);
}
console.error("ERROR: unexpected completion order " + JSON.stringify(order));
process.exit(2);

